function StarField() {
  const stars = useMemo(() => Array.from({ length: 120 }, (_, i) => ({
    id: i, x: Math.random() * 100, y: Math.random() * 60,
    size: Math.random() * 1.8 + 0.4, delay: Math.random() * 5, duration: 2 + Math.random() * 4,
  })), []);
  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden">
      {stars.map(s => (
        <motion.div key={s.id} className="absolute rounded-full"
          style={{ left: `${s.x}%`, top: `${s.y}%`, width: s.size, height: s.size, background: "white" }}
          animate={{ opacity: [0.1, 0.9, 0.1], scale: [1, 1.4, 1] }}
          transition={{ duration: s.duration, delay: s.delay, repeat: Infinity, ease: "easeInOut" }} />
      ))}
    </div>
  );
}

function GoldDust() {
  const particles = useMemo(() => Array.from({ length: 40 }, (_, i) => ({
    id: i, x: Math.random() * 100, drift: (Math.random() - 0.5) * 60,
    duration: 8 + Math.random() * 12, delay: Math.random() * 15,
    size: Math.random() * 2.5 + 1, opacity: Math.random() * 0.5 + 0.2,
  })), []);
  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden">
      {particles.map(p => (
        <motion.div key={p.id} className="absolute rounded-full"
          style={{ left: `${p.x}%`, bottom: "-5%", width: p.size, height: p.size, background: "#D4AF37", opacity: 0 }}
          animate={{ y: [0, -900], x: [0, p.drift], opacity: [0, p.opacity, p.opacity, 0] }}
          transition={{ duration: p.duration, delay: p.delay, repeat: Infinity, ease: "linear", repeatDelay: Math.random() * 3 }} />
      ))}
    </div>
  );
}

function CinematicLantern({ index }) {
  const cfg = useMemo(() => {
    const depth = Math.random();
    return {
      left: Math.random() * 110 - 5, startY: 60 + Math.random() * 80,
      duration: 7 + Math.random() * 9, delay: index * 0.35,
      size: 14 + depth * 28, blur: (1 - depth) * 5,
      glowSize: 8 + depth * 20, glowOpacity: 0.3 + depth * 0.5,
      driftX: (Math.random() - 0.5) * 80,
    };
  }, [index]);
  return (
    <motion.div
      initial={{ y: `${cfg.startY}vh`, x: `${cfg.left}vw`, opacity: 0 }}
      animate={{ y: "-15vh", x: `calc(${cfg.left}vw + ${cfg.driftX}px)`, opacity: [0, 1, 1, 0.8, 0] }}
      transition={{ duration: cfg.duration, repeat: Infinity, ease: "easeInOut", delay: cfg.delay }}
      className="absolute pointer-events-none"
      style={{ width: cfg.size, filter: `blur(${cfg.blur}px)` }}
    >
      <div style={{ position: "relative" }}>
        <div style={{ position: "absolute", inset: -cfg.glowSize, background: `radial-gradient(circle, rgba(255,200,50,${cfg.glowOpacity}) 0%, transparent 70%)`, borderRadius: "50%", filter: "blur(6px)" }} />
        <svg viewBox="0 0 40 70" style={{ width: cfg.size, height: cfg.size * 1.75, display: "block" }}>
          <defs>
            <radialGradient id={`lg${index}`} cx="50%" cy="40%" r="55%">
              <stop offset="0%" stopColor="#FFFBE8" /><stop offset="40%" stopColor="#FFD040" /><stop offset="100%" stopColor="#B8860B" />
            </radialGradient>
            <radialGradient id={`inner${index}`} cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="rgba(255,255,220,0.9)" /><stop offset="100%" stopColor="rgba(255,200,50,0)" />
            </radialGradient>
          </defs>
          <path d="M20 4 L36 16 L34 50 L20 62 L6 50 L4 16 Z" fill={`url(#lg${index})`} />
          <ellipse cx="20" cy="32" rx="9" ry="11" fill={`url(#inner${index})`} />
          <rect x="17" y="0" width="6" height="6" rx="2" fill="#B8860B" />
          <line x1="4" y1="22" x2="36" y2="22" stroke="rgba(255,255,255,0.25)" strokeWidth="0.5" />
          <line x1="4" y1="44" x2="36" y2="44" stroke="rgba(255,255,255,0.25)" strokeWidth="0.5" />
          <line x1="20" y1="62" x2="20" y2="70" stroke="#B8860B" strokeWidth="1.5" />
          <circle cx="20" cy="70" r="2" fill="#D4AF37" />
        </svg>
      </div>
    </motion.div>
  );
}

