function Countdown({ target }) {
  const [t, setT] = useState({ Days: 0, Hrs: 0, Min: 0, Sec: 0 });
  useEffect(() => {
    const tick = () => {
      const d = target - new Date();
      if (d <= 0) return;
      setT({ Days: Math.floor(d / 86400000), Hrs: Math.floor((d / 3600000) % 24), Min: Math.floor((d / 60000) % 60), Sec: Math.floor((d / 1000) % 60) });
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [target]);
  return (
    <div style={{ display: "flex", justifyContent: "space-around", background: "rgba(0,20,50,0.6)", backdropFilter: "blur(20px)", border: "0.5px solid rgba(212,175,55,0.25)", borderRadius: 28, padding: "28px 20px", boxShadow: "0 0 60px rgba(0,0,0,0.5), inset 0 0 30px rgba(212,175,55,0.05)", position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", top: 0, left: "10%", right: "10%", height: 1, background: "linear-gradient(to right, transparent, rgba(212,175,55,0.4), transparent)" }} />
      {Object.entries(t).map(([k, v]) => (
        <div key={k} style={{ textAlign: "center", flex: 1 }}>
          <AnimatePresence mode="popLayout">
            <motion.span key={v} initial={{ y: -20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 20, opacity: 0 }}
              transition={{ duration: 0.35, ease: [0.4, 0, 0.2, 1] }}
              style={{ display: "block", fontFamily: "'Cinzel', serif", fontSize: 30, color: "#D4AF37", fontWeight: 400, lineHeight: 1, filter: "drop-shadow(0 0 12px rgba(212,175,55,0.6))" }}>
              {String(v).padStart(2, "0")}
            </motion.span>
          </AnimatePresence>
          <span style={{ fontFamily: "'Cinzel', serif", fontSize: 7, color: "rgba(212,175,55,0.45)", textTransform: "uppercase", letterSpacing: "0.4em", display: "block", marginTop: 8 }}>{k}</span>
        </div>
      ))}
    </div>
  );
}

